    )
}

object PhysiologyFigure {
    const val width=1000f;const val height=600f
    val marks=listOf(NutritionMark("cell-boundary",465f,310f),NutritionMark("mitochondrion",730f,280f),NutritionMark("dissolved-exchange",280f,500f))
    fun fit(w: Float,h: Float)=NutritionFigure.fit(w,h)
    fun at(x: Float,y: Float)=marks.minByOrNull {(x-it.x)*(x-it.x)+(y-it.y)*(y-it.y)}
        ?.takeIf {(x-it.x)*(x-it.x)+(y-it.y)*(y-it.y)<=38f*38f}?.id
}
